const cPaid=c=>(c.pays||[]).filter(p=>p.st!=='wait').reduce((s,p)=>s+(+p.amount||0),0);
const cWait=c=>(c.pays||[]).filter(p=>p.st==='wait').reduce((s,p)=>s+(+p.amount||0),0);
const cRem=c=>Math.max(0,(+c.debt||0)-cPaid(c));
const cDone=c=>cRem(c)<=0;
