  const ins=[...V.querySelectorAll('input[data-wz]')];ins.forEach((el,i)=>el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(ins[i+1])ins[i+1].focus();else ACT[wz.step===4?'wzSave':'wzNext']()}}));
