  const one=ids.length===1?validated().find(r=>String(r.id)===String(ids[0])):null,F1=one?famOf(one):[],canPs=one&&can('split')&&!one.full&&one.level<2&&sources.length>1&&!F1.some(r=>r.sentBid);
