ACT.pyD=d=>{pyRead();const p=sv.qa.p;if(p.dir===d.d||(p.m==='pos'&&d.d==='out'))return;p.dir=d.d;p.amount=pyLeft(p);if(p.m==='cust')pyCuCap(p);svKeep();qaRe()};
