    if(/^(\d)\1{5}$/.test(pin)||'0123456789'.includes(pin)||'9876543210'.includes(pin)){S.m='set1';S.pin='';S.first='';S.err='رمز خیلی ساده است (مثل ۱۱۱۱۱۱ یا ۱۲۳۴۵۶)؛ رمز دیگری انتخاب کنید';S.shake=true;setTimeout(lockDraw,120);return}
